22	static void queue_pages_hugetlb_pmd_range(struct vm_area_struct *vma,
23			pmd_t *pmd, const nodemask_t *nodes, unsigned long flags,
24					    void *private)
25	{
26	#ifdef CONFIG_HUGETLB_PAGE
27		int nid;
28		struct page *page;
29	
30		spin_lock(&vma->vm_mm->page_table_lock);
31		page = pte_page(huge_ptep_get((pte_t *)pmd));
32		nid = page_to_nid(page);
33		if (node_isset(nid, *nodes) == !!(flags & MPOL_MF_INVERT))
34			goto unlock;
35		/* With MPOL_MF_MOVE, we migrate only unshared hugepage. */
36		if (flags & (MPOL_MF_MOVE_ALL) ||
37		    (flags & MPOL_MF_MOVE && page_mapcount(page) == 1))
38			isolate_huge_page(page, private);
39	unlock:
40		spin_unlock(&vma->vm_mm->page_table_lock);
41	#else
42		BUG();
43	#endif
44	}
