46	static inline int queue_pages_pmd_range(struct vm_area_struct *vma, pud_t *pud,
47			unsigned long addr, unsigned long end,
48			const nodemask_t *nodes, unsigned long flags,
49			void *private)
50	{
51		pmd_t *pmd;
52		unsigned long next;
53	
54		pmd = pmd_offset(pud, addr);
55		do {
56			next = pmd_addr_end(addr, end);
57			if (!pmd_present(*pmd))
58				continue;
59			if (pmd_huge(*pmd) && is_vm_hugetlb_page(vma)) {
60				queue_pages_hugetlb_pmd_range(vma, pmd, nodes,
61							flags, private);
62				continue;
63			}
64			split_huge_page_pmd(vma, addr, pmd);
65			if (pmd_none_or_trans_huge_or_clear_bad(pmd))
66				continue;
67			if (queue_pages_pte_range(vma, pmd, addr, next, nodes,
68					    flags, private))
69				return -EIO;
70		} while (pmd++, addr = next, addr != end);
71		return 0;
72	}
