#!/usr/bin/env python3
"""Source-level security-invariant check for the CVE-2014-3940 port.

Runs against a checked-out tree (the validator applies generated.patch into a
temporary clone and runs this with cwd = that tree). Exits 0 only if both
hugetlb_entry callbacks guard non-present huge ptes before touching page
metadata.
"""
import re
import sys
from pathlib import Path


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def function_body(text: str, start_marker: str) -> str:
    start = text.index(start_marker)
    brace = text.index("{", start)
    depth = 0
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[brace:i + 1]
    raise AssertionError(f"unterminated function at {start_marker}")


def main() -> int:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    errors = []

    task_mmu = read(root / "fs/proc/task_mmu.c")
    body = function_body(task_mmu, "static int gather_hugetbl_stats(pte_t *pte,")
    present = body.index("if (!pte_present(*pte))")
    use = body.index("page = pte_page(*pte);")
    if present >= use:
        errors.append("task_mmu.c: !pte_present guard must precede pte_page(*pte)")
    if "pte_none(*pte)" in body:
        errors.append("task_mmu.c: gather_hugetbl_stats still uses pte_none(*pte)")
    if "return 0;" not in body[present:use]:
        errors.append("task_mmu.c: non-present branch must return before pte_page()")

    mempolicy = read(root / "mm/mempolicy.c")
    body = function_body(mempolicy, "static void queue_pages_hugetlb_pmd_range(")
    if "pte_t entry;" not in body:
        errors.append("mempolicy.c: missing local pte_t entry")
    get = body.index("entry = huge_ptep_get((pte_t *)pmd);")
    guard = body.index("if (!pte_present(entry))")
    use = body.index("page = pte_page(entry);")
    if not (get < guard < use):
        errors.append("mempolicy.c: order must be huge_ptep_get -> !pte_present -> pte_page")
    if "if (!pte_present(entry))" in body:
        after_guard = body[guard:]
        if "goto unlock;" not in after_guard[: after_guard.index("page = pte_page(entry);")]:
            errors.append("mempolicy.c: non-present branch must goto unlock before pte_page()")
    if "pte_page(huge_ptep_get(" in body:
        errors.append("mempolicy.c: unconditional pte_page(huge_ptep_get(...)) still present")
    if "spin_lock(&vma->vm_mm->page_table_lock);" not in body:
        errors.append("mempolicy.c: target page_table_lock not preserved")
    if "spin_unlock(&vma->vm_mm->page_table_lock);" not in body:
        errors.append("mempolicy.c: target page_table_unlock not preserved")

    if errors:
        print("FAIL")
        for error in errors:
            print(" -", error)
        return 1
    print("PASS: both hugetlb_entry callbacks guard non-present huge ptes before page dereference")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

