    if "spin_unlock(&vma->vm_mm->page_table_lock);" not in body:
        raise AssertionError("target page_table_lock unlock not preserved")


def main() -> int:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    try:
        check_task_mmu(root)
